function exportCsv() {
  const rows = [...morse.$$("body > div.mn > div.row2 > div.tbl table tr")];
  const csv = rows.map(tr =>
    [...tr.children]
      .map(c => '"' + c.textContent.trim().replace(/"/g, '""') + '"')
      .join(",")
  ).join("\n");
  const a = morse.el("a", {
    href: URL.createObjectURL(new Blob([csv], { type: "text/csv" })),
    download: "orders.csv"
  });
  document.body.appendChild(a);
  a.click();
  a.remove();
  morse.toast("Exported " + Math.max(rows.length - 1, 0) + " orders");
}

