results.js:
morse.watch(".tbl", el => {
  if (el.querySelector(".morse-search")) return;
  const input = morse.el("input", {
    class: "morse-search",
    type: "search",
    placeholder: "Search orders…",
    "aria-label": "Search orders"
  });
  morse.on(input, "input", () => {
    const q = input.value.trim().toLowerCase();
    morse.$$(".tbl tbody tr").forEach(tr => {
      const text = tr.textContent.toLowerCase();
      tr.classList.toggle("morse-hide", q !== "" && !text.includes(q));
    });
  });
  const sc = el.querySelector(".sc");
  if (sc) el.insertBefore(input, sc);
});

