results.js:
morse.watch("div.tbl table thead tr th.am", el => {
  if (el.dataset.sortable) return;
  el.dataset.sortable = "1";
  el.style.cursor = "pointer";
  el.title = "Sort by amount";
  let asc = false;
  morse.on(el, "click", () => {
    const table = el.closest("table");
    const tbody = table.querySelector("tbody");
    const idx = Array.from(el.parentElement.children).indexOf(el);
    const rows = Array.from(tbody.querySelectorAll("tr"));
    asc = !asc;
    rows.sort((a, b) => {
      const av = parseFloat(a.children[idx]?.textContent.replace(/[^0-9.\-]/g, "")) || 0;
      const bv = parseFloat(b.children[idx]?.textContent.replace(/[^0-9.\-]/g, "")) || 0;
      return asc ? av - bv : bv - av;
    });
    rows.forEach(r => tbody.appendChild(r));
    el.textContent = "Amount " + (asc ? "▲" : "▼");
  });
});

morse.watch("div.tbl table thead tr th.am", el => {
  el.style.cursor = "pointer";
  el.title = "Click to sort by amount";
  if (!el.dataset.sortBound) {
    el.dataset.sortBound = "1";
    el.addEventListener("click", () => {
      const table = el.closest("table");
      const tbody = table.querySelector("tbody");
      const idx = Array.from(el.parentElement.children).indexOf(el);
      const asc = el.dataset.dir !== "asc";
      el.parentElement.querySelectorAll("th").forEach(h => delete h.dataset.dir);
      el.dataset.dir = asc ? "asc" : "desc";
      const rows = Array.from(tbody.querySelectorAll("tr"));
      const num = s => parseFloat(String(s).replace(/[^0-9.\-]/g, "")) || 0;
      rows.sort((a, b) => {
        const va = num(a.children[idx]?.textContent);
        const vb = num(b.children[idx]?.textContent);
        return asc ? va - vb : vb - va;
      });
      rows.forEach(r => tbody.appendChild(r));
      morse.toast("Sorted by amount " + (asc ? "(low to high)" : "(high to low)"));
    });
  }
});

morse.watch("div.tbl table thead tr th.am", el => {
  if (el.dataset.sortable) return;
  el.dataset.sortable = "1";
  el.style.cursor = "pointer";
  el.style.userSelect = "none";
  el.title = "Click to sort by amount";
  let dir = 1;
  el.addEventListener("click", () => {
    const table = el.closest("table");
    const tbody = table.querySelector("tbody");
    const idx = Array.from(el.parentElement.children).indexOf(el);
    const rows = Array.from(tbody.querySelectorAll("tr"));
    const val = r => parseFloat(r.children[idx].textContent.replace(/[^0-9.\-]/g, "")) || 0;
    rows.sort((a, b) => (val(a) - val(b)) * dir);
    rows.forEach(r => tbody.appendChild(r));
    dir = -dir;
    el.textContent = "Amount " + (dir === 1 ? "▲" : "▼");
  });
});

