morse.watch('[role="option"][data-i]', function (el) {
  // no per-element setup needed
});

function currentIndex() {
  var rows = morse.$$('[role="option"][data-i]');
  for (var i = 0; i < rows.length; i++) {
    if (rows[i].getAttribute('aria-selected') === 'true') return i;
  }
  return -1;
}

function moveTo(delta) {
  var rows = morse.$$('[role="option"][data-i]');
  if (!rows.length) return;
  var i = currentIndex();
  var next = Math.max(0, Math.min(rows.length - 1, i + delta));
  if (next === i && i !== -1) return;
  var target = rows[next < 0 ? 0 : next];
  target.click();
  target.scrollIntoView({ block: 'nearest' });
  target.focus && target.focus();
}

morse.on(document, 'keydown', function (e) {
  if (e.defaultPrevented || e.ctrlKey || e.metaKey || e.altKey) return;
  var t = e.target;
  if (t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))) return;
  if (e.key === 'j') { e.preventDefault(); moveTo(1); }
  else if (e.key === 'k') { e.preventDefault(); moveTo(-1); }
});

morse.toast('Use J and K to move through the email list');

morse.on(document, "keydown", e => {
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  if (e.key !== "j" && e.key !== "k") return;
  const t = e.target;
  if (t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))) return;
  const rows = Array.from(morse.$$('[role="option"][data-i]'));
  if (!rows.length) return;
  const cur = rows.findIndex(r => r.getAttribute("aria-selected") === "true");
  const next = e.key === "j"
    ? Math.min(cur + 1, rows.length - 1)
    : Math.max(cur - 1, 0);
  if (next === cur) return;
  e.preventDefault();
  const row = rows[next];
  row.click();
  row.scrollIntoView({ block: "nearest" });
});

morse.on(document, "keydown", e => {
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  if (e.key !== "j" && e.key !== "k") return;
  if (e.target && e.target.closest && e.target.closest("input, textarea, select, [contenteditable='true']")) return;
  const rows = Array.from(morse.$$('section[aria-label="Message list"] [role="option"][data-i]'))
    .sort((a, b) => Number(a.dataset.i) - Number(b.dataset.i));
  if (!rows.length) return;
  const cur = rows.findIndex(r => r.getAttribute("aria-selected") === "true");
  let next = cur < 0 ? 0 : (e.key === "j" ? cur + 1 : cur - 1);
  next = Math.max(0, Math.min(rows.length - 1, next));
  const row = rows[next];
  row.click();
  row.scrollIntoView({ block: "nearest" });
  e.preventDefault();
});

