morse.watch('div[aria-label="Formatting"]', bar => {
  if (bar.querySelector('button.date-btn')) return;
  const btn = morse.el('button', { class: 'date-btn', title: 'Insert today\'s date', text: 'Date' });
  morse.on(btn, 'click', () => {
    const ed = morse.$('div[role="textbox"]');
    if (!ed) return;
    ed.focus();
    const d = new Date().toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
    document.execCommand('insertText', false, d);
  });
  bar.appendChild(btn);
});

morse.watch('div[aria-label="Formatting"]', bar => {
  if (bar.querySelector('button.date-btn')) return;
  const btn = morse.el('button', {
    class: 'date-btn',
    title: "Insert today's date",
    text: 'Date',
    on: {
      click: () => {
        const d = new Date();
        const s = d.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
        const sel = window.getSelection();
        const box = morse.$('div[role="textbox"]');
        if (box) box.focus();
        if (sel && sel.rangeCount) {
          const r = sel.getRangeAt(0);
          r.deleteContents();
          r.insertNode(document.createTextNode(s));
          r.collapse(false);
        } else if (box) {
          box.append(document.createTextNode(s));
        }
        morse.toast('Inserted ' + s);
      }
    }
  });
  bar.append(btn);
});

morse.watch('div[aria-label="Formatting"]', bar => {
  if (bar.querySelector('.dt-btn')) return;
  const btn = morse.el('button', {
    class: 'dt-btn',
    title: "Insert today's date",
    text: 'Date',
    on: { click: () => {
      const d = new Date();
      const s = d.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
      const sel = window.getSelection();
      const ed = document.querySelector('div[role="textbox"]');
      if (ed) ed.focus();
      document.execCommand('insertText', false, s);
    } }
  });
  bar.appendChild(btn);
});

