morse.watch("body > main > header[role='banner'] > div.h7r", el => {
  if (el.querySelector("[data-copy-md]")) return;
  const btn = morse.el("button", { type: "button", "data-copy-md": "", text: "Copy as Markdown", title: "Copy conversation as markdown" , on: { click: () => {
    const lines = [];
    morse.$$("section[aria-label='Conversation'] .msg[data-role]").forEach(m => {
      const role = m.getAttribute("data-role") === "user" ? "**You**" : "**Parley**";
      const text = m.innerText.trim();
      lines.push(`${role}\n\n${text}`);
    });
    const md = lines.join("\n\n---\n\n");
    navigator.clipboard.writeText(md).then(
      () => morse.toast("Conversation copied as Markdown"),
      () => morse.toast("Copy failed")
    );
  } } });
  el.insertBefore(btn, el.firstChild);
});

const toMarkdown = () => morse.$$('section[aria-label="Conversation"] .msg[data-role]')
  .map(m => {
    const who = m.dataset.role === 'user' ? 'You' : 'Parley';
    return `**${who}:**\n\n${m.innerText.trim()}`;
  })
  .join('\n\n---\n\n');

morse.watch('body > main > header[role="banner"] > div.h7r', (bar) => {
  if (bar.querySelector('[data-copy-md]')) return;
  const btn = morse.el('button', {
    type: 'button',
    'data-copy-md': '',
    text: 'Copy as Markdown',
    on: {
      click: async () => {
        const md = toMarkdown();
        if (!md) return morse.toast('No messages to copy');
        try {
          await navigator.clipboard.writeText(md);
          morse.toast('Conversation copied as Markdown');
        } catch (e) {
          morse.toast('Copy failed');
        }
      }
    }
  });
  bar.insertBefore(btn, bar.firstChild);
}, { live: true });

const copyConvo = () => {
  const msgs = morse.$$('section[aria-label="Conversation"] .msg[data-role]');
  if (!msgs.length) { morse.toast("No messages to copy"); return; }
  const md = msgs.map(m => {
    const who = m.dataset.role === "user" ? "**You**" : "**Parley**";
    return who + "\n\n" + m.innerText.trim();
  }).join("\n\n---\n\n");
  navigator.clipboard.writeText(md).then(
    () => morse.toast("Conversation copied as Markdown"),
    () => morse.toast("Copy failed")
  );
};

