morse.watch("#__next > div:nth-of-type(2) > main > div:nth-of-type(1)", bar => {
  if (bar.querySelector("[data-sort-price]")) return;

  const priceOf = el => {
    const m = el.textContent.match(/\$\s*([\d,]+(?:\.\d+)?)/);
    return m ? parseFloat(m[1].replace(/,/g, "")) : Infinity;
  };

  const btn = morse.el("button", {
    "data-sort-price": "",
    type: "button",
    text: "Sort by price",
    style: "margin-left:auto;font:inherit;font-size:14px;color:inherit;background:transparent;border:1px solid currentColor;border-radius:999px;padding:4px 12px;cursor:pointer;opacity:0.85",
    on: {
      click: () => {
        const grid = morse.$("#__next > div:nth-of-type(2) > main > div:nth-of-type(2)");
        if (!grid) return;
        const items = Array.from(grid.children);
        items.sort((a, b) => {
          const pa = priceOf(a), pb = priceOf(b);
          return pa === pb ? 0 : pa < pb ? -1 : 1;
        });
        items.forEach(item => grid.appendChild(item));
        morse.toast("Sorted by price, lowest first");
      }
    }
  });

  bar.appendChild(btn);
});

morse.watch("#__next > div:nth-of-type(2) > main > div:nth-of-type(1)", bar => {
  if (bar.querySelector("[data-morse-sort]")) return;
  const btn = morse.el("button", {
    "data-morse-sort": "",
    text: "Sort: price low to high",
    style: "margin-left:auto;font:inherit;font-size:14px;color:inherit;background:none;border:1px solid currentColor;border-radius:6px;padding:4px 10px;cursor:pointer;opacity:0.85",
    on: {
      click: () => {
        const grid = morse.$("#__next > div:nth-of-type(2) > main > div:nth-of-type(2)");
        if (!grid) return;
        const cards = Array.from(grid.children);
        const priceOf = card => {
          const m = (card.textContent.match(/\$\s?([\d,]+(?:\.\d+)?)/) || [])[1];
          return m ? parseFloat(m.replace(/,/g, "")) : Infinity;
        };
        cards.sort((a, b) => priceOf(a) - priceOf(b)).forEach(c => grid.appendChild(c));
        morse.toast("Sorted by price, lowest first");
      }
    }
  });
  bar.appendChild(btn);
});

