results.js:
morse.watch('[data-testid="player-controls"] .btns', (btns) => {
  if (btns.querySelector('.sleep-timer')) return;
  let remaining = 0;
  let timerId = null;
  const btn = morse.el('button', {
    class: 'sleep-timer',
    'aria-label': 'Sleep timer',
    text: 'Sleep',
    on: {
      click: () => {
        const options = [0, 15, 30, 60];
        const next = options[(options.indexOf(remaining) + 1) % options.length] ?? 0;
        clearInterval(timerId);
        remaining = next;
        if (remaining === 0) {
          btn.textContent = 'Sleep';
          morse.toast('Sleep timer off');
          return;
        }
        btn.textContent = remaining + 'm';
        morse.toast('Music will pause in ' + remaining + ' minutes');
        timerId = setTimeout(() => {
          const pause = morse.$('[data-testid="play-pause"]');
          if (pause && pause.getAttribute('aria-label') === 'Pause') pause.click();
          remaining = 0;
          btn.textContent = 'Sleep';
        }, remaining * 60 * 1000);
      }
    }
  });
  btns.appendChild(btn);
});

let endAt = 0;
let mins = 0;
const steps = [0, 5, 15, 30];

morse.watch('[data-testid="player-controls"] .btns', (row) => {
  if (row.querySelector('[data-sleep-timer]')) return;
  row.appendChild(morse.el('button', {
    'data-sleep-timer': '',
    'aria-label': 'Sleep timer',
    title: 'Sleep timer (off, 5, 15, 30 min)',
    text: '☾',
    on: { click: () => {
      mins = steps[(steps.indexOf(mins) + 1) % steps.length];
      endAt = mins ? Date.now() + mins * 60000 : 0;
      morse.toast(mins ? `Sleep timer: ${mins} min` : 'Sleep timer off');
    }}
  }));
});

morse.every(1000, () => {
  const b = morse.$('[data-sleep-timer]');
  if (endAt && Date.now() >= endAt) {
    endAt = 0;
    mins = 0;
    const pause = morse.$('button[data-testid="play-pause"][aria-label="Pause"]');
    if (pause) pause.click();
    morse.toast('Sleep timer: playback paused');
  }
  if (b) b.textContent = endAt ? Math.ceil((endAt - Date.now()) / 60000) + 'm' : '☾';
});

morse.watch('div[data-testid="player-controls"] .btns', (row) => {
  const steps = [0, 15, 30, 60];
  let i = 0, timer = null;
  const btn = morse.el('button', {
    'aria-label': 'Sleep timer',
    title: 'Sleep timer: off',
    text: '☾',
    on: { click: () => {
      i = (i + 1) % steps.length;
      clearTimeout(timer);
      timer = null;
      const mins = steps[i];
      if (mins) {
        timer = setTimeout(() => {
          const pp = morse.$('button[data-testid="play-pause"]');
          if (pp && pp.getAttribute('aria-label') === 'Pause') pp.click();
          morse.toast('Sleep timer: playback paused');
          i = 0;
          btn.textContent = '☾';
          btn.title = 'Sleep timer: off';
        }, mins * 60000);
        btn.textContent = mins + 'm';
        morse.toast(`Sleep timer set: ${mins} min`);
      } else {
        btn.textContent = '☾';
        morse.toast('Sleep timer off');
      }
      btn.title = mins ? `Sleep timer: ${mins} min` : 'Sleep timer: off';
    }}
  });
  row.appendChild(btn);
});

