    class: 'jump-newest',
    type: 'button',
    text: 'Jump to newest',
    'aria-label': 'Jump to newest line',
    on: { click: () => {
      const list = morse.$('div[aria-label="Log\\ lines"]');
      if (list) list.scrollTop = list.scrollHeight;
    }}
  }));
});

