results.js:
const bar = morse.$("hearth-bar");
const wrap = morse.$("#where")?.parentElement;
const btn = morse.el("button", { id: "morse-all-off", text: "All devices off", "aria-label": "Turn all devices off" });
morse.on(btn, "click", () => {
  morse.$$("device-card").forEach(card => {
    const b = card.shadowRoot?.querySelector("button[aria-label$=': on']");
    if (b && !b.disabled) b.click();
  });
  morse.toast("All devices turned off");
});
const header = morse.$("#where");
if (header) {
  const row = morse.el("div", { style: "display:flex;align-items:center;gap:12px;" });
  header.parentNode.insertBefore(row, header);
  row.appendChild(header);
  row.appendChild(btn);
}

